CREATE FUNCTION public.notify_cnc_config_changed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    row_data RECORD;
BEGIN
    IF TG_OP = 'DELETE' THEN
        row_data := OLD;
    ELSE
        row_data := NEW;
    END IF;

    IF TG_TABLE_NAME = 'machine_variables' THEN
        PERFORM pg_notify('cnc_config_changed', 'machine:' || row_data.machine_id);
    ELSE
        PERFORM pg_notify('cnc_config_changed', 'variables');
    END IF;
    RETURN row_data;
END;
$$;


