CREATE FUNCTION public.notify_machines_changed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        PERFORM pg_notify('machines_changed', OLD.id::text);
        RETURN OLD;
    END IF;

    IF TG_OP = 'INSERT' THEN
        IF NEW.is_monitor THEN
            PERFORM pg_notify('machines_changed', NEW.id::text);
        END IF;
        RETURN NEW;
    END IF;

    IF (NEW.is_monitor, NEW.is_deleted, NEW.status, NEW.live_ip, NEW.port, NEW.username,
        NEW.password, NEW.brand_id, NEW.controller_id, NEW.controller_version_type)
       IS DISTINCT FROM
       (OLD.is_monitor, OLD.is_deleted, OLD.status, OLD.live_ip, OLD.port, OLD.username,
        OLD.password, OLD.brand_id, OLD.controller_id, OLD.controller_version_type) THEN
        PERFORM pg_notify('machines_changed', NEW.id::text);
    END IF;
    RETURN NEW;
END;
$$;


